package io.knowledgebrain.learning;
import java.util.*;
import java.time.*;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
import org.flywaydb.core.Flyway;
import org.postgresql.ds.PGSimpleDataSource;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.web.server.ResponseStatusException;
import static org.junit.jupiter.api.Assertions.*;
import io.knowledgebrain.contracts.learning.roadmap.v1.*;
@EnabledIfEnvironmentVariable(named="BRAIN_TEST_LEARNING_DATABASE_URL",matches=".+")
class RoadmapStoreIntegrationTest {
 RoadmapStore store;JdbcTemplate sql;UUID space,actor;String trace="a".repeat(32);
 @BeforeEach void setup(){var ds=new PGSimpleDataSource();ds.setURL(System.getenv("BRAIN_TEST_LEARNING_DATABASE_URL"));ds.setUser("brain_learning");ds.setPassword(System.getenv("BRAIN_TEST_LEARNING_DATABASE_PASSWORD"));Flyway.configure().dataSource(ds).locations("classpath:db/migration").load().migrate();store=new RoadmapStore(ds,Clock.systemUTC());sql=new JdbcTemplate(ds);var ids=new UuidV7(Clock.systemUTC());space=ids.next();actor=ids.next();}
 RoadmapGraph.Edit graph(){return new RoadmapGraph.Edit(List.of(new RoadmapGraph.NodeEdit("new:a","First","Detail A"),new RoadmapGraph.NodeEdit("new:b","Second","Detail B")),List.of(new RoadmapGraph.EdgeEdit("new:e","PREREQUISITE_OF","new:a","new:b")));}
 RoadmapGraph.Edit edit(RoadmapStore.Roadmap value){return new RoadmapGraph.Edit(value.nodes().stream().map(n->new RoadmapGraph.NodeEdit(n.nodeId().toString(),n.title(),n.description())).toList(),value.edges().stream().map(e->new RoadmapGraph.EdgeEdit(e.edgeId().toString(),e.kind(),e.sourceNodeId().toString(),e.targetNodeId().toString())).toList());}
 int events(UUID id){return sql.queryForObject("SELECT count(*) FROM outbox_event WHERE aggregateid=?",Integer.class,id);}
 @Test void graphIdsGeneratedByOwnerAndEveryRevisionHasExactFullSnapshotOutbox()throws Exception{var root=store.create(space,actor,"Roadmap","description",trace);assertEquals(1,root.version());assertTrue(root.nodes().isEmpty());var graph=store.graph(space,root.roadmapId(),actor,1,graph(),trace);assertEquals(2,graph.version());assertEquals(2,graph.nodes().size());assertEquals(1,graph.edges().size());graph.nodes().forEach(n->assertEquals(7,n.nodeId().version()));assertEquals(graph,store.get(space,root.roadmapId()));assertEquals(graph,store.graph(space,root.roadmapId(),actor,2,edit(graph),trace));assertEquals(2,events(root.roadmapId()));assertEquals(graph,store.history(space,root.roadmapId(),Long.MAX_VALUE,10).getFirst().snapshot());var wire=sql.queryForObject("SELECT payload FROM outbox_event WHERE aggregateid=? AND type='RoadmapGraphChanged'",byte[].class,root.roadmapId());var envelope=RoadmapEventEnvelopeV1.parseFrom(wire);var payload=RoadmapChangedPayloadV1.parseFrom(envelope.getPayload());assertEquals("learning-service",envelope.getProducer());assertEquals(space.toString(),envelope.getSpaceId());assertEquals(actor.toString(),envelope.getActorId());assertEquals(trace,envelope.getTraceId());assertEquals(2,payload.getVersion());assertEquals(2,payload.getNodesCount());assertEquals(graph.edges().getFirst().edgeId().toString(),payload.getEdges(0).getEdgeId());assertEquals(store.history(space,root.roadmapId(),3,1).getFirst().revisionId().toString(),payload.getRevisionId());}
 @Test void staleInvalidAndForeignGraphWritesLeaveCanonicalTablesRevisionAndOutboxUnchanged(){var root=store.create(space,actor,"Protected","",trace);var value=store.graph(space,root.roadmapId(),actor,1,graph(),trace);assertThrows(ResponseStatusException.class,()->store.metadata(space,root.roadmapId(),actor,1,"stale","",false,trace));var other=store.create(space,actor,"Other","",trace);var foreign=store.graph(space,other.roadmapId(),actor,1,graph(),trace);var bad=new RoadmapGraph.Edit(List.of(new RoadmapGraph.NodeEdit(foreign.nodes().getFirst().nodeId().toString(),"Borrowed","")),List.of());assertThrows(ResponseStatusException.class,()->store.graph(space,root.roadmapId(),actor,2,bad,trace));var nodes=edit(value).nodes();var a=nodes.get(0).key();var b=nodes.get(1).key();var cyclic=new RoadmapGraph.Edit(nodes,List.of(new RoadmapGraph.EdgeEdit("new:x","PREREQUISITE_OF",a,b),new RoadmapGraph.EdgeEdit("new:y","REQUIRED_FOR",b,a)));assertThrows(ResponseStatusException.class,()->store.graph(space,root.roadmapId(),actor,2,cyclic,trace));assertEquals(value,store.get(space,root.roadmapId()));assertEquals(2,events(root.roadmapId()));assertEquals(2,store.history(space,root.roadmapId(),Long.MAX_VALUE,10).size());assertThrows(ResponseStatusException.class,()->store.get(actor,root.roadmapId()));}
 @Test void nodeAndEdgeExclusionRetiresIdsWithoutErasingSnapshotsAndCannotResurrect(){var root=store.create(space,actor,"Lifecycle","",trace);var value=store.graph(space,root.roadmapId(),actor,1,graph(),trace);var oldHistory=store.history(space,root.roadmapId(),3,2);var first=value.nodes().getFirst();var reduced=store.graph(space,root.roadmapId(),actor,2,new RoadmapGraph.Edit(List.of(new RoadmapGraph.NodeEdit(first.nodeId().toString(),first.title(),first.description())),List.of()),trace);assertEquals(3,reduced.version());assertEquals(1,sql.queryForObject("SELECT count(*) FROM roadmap_node WHERE roadmap_id=? AND state='RETIRED'",Integer.class,root.roadmapId()));assertEquals(1,sql.queryForObject("SELECT count(*) FROM roadmap_edge WHERE roadmap_id=? AND state='RETIRED'",Integer.class,root.roadmapId()));assertThrows(ResponseStatusException.class,()->store.graph(space,root.roadmapId(),actor,3,edit(value),trace));assertEquals(oldHistory,store.history(space,root.roadmapId(),3,2));var retired=store.metadata(space,root.roadmapId(),actor,3,null,null,true,trace);assertEquals("RETIRED",retired.state());assertThrows(ResponseStatusException.class,()->store.get(space,root.roadmapId()));assertTrue(store.list(space,null,20).items().isEmpty());assertEquals(4,store.history(space,root.roadmapId(),Long.MAX_VALUE,10).size());assertEquals(4,events(root.roadmapId()));assertThrows(ResponseStatusException.class,()->store.graph(space,root.roadmapId(),actor,4,graph(),trace));}
 @Test void concurrentMetadataAndGraphHaveOneWinnerAndSnapshotMatchesVersion()throws Exception{var root=store.create(space,actor,"Concurrent","",trace);try(var pool=java.util.concurrent.Executors.newFixedThreadPool(2)){var barrier=new java.util.concurrent.CyclicBarrier(2);var a=pool.submit(()->{barrier.await();try{store.graph(space,root.roadmapId(),actor,1,graph(),trace);return true;}catch(ResponseStatusException e){assertEquals(412,e.getStatusCode().value());return false;}});var b=pool.submit(()->{barrier.await();try{store.metadata(space,root.roadmapId(),actor,1,"Changed","",false,trace);return true;}catch(ResponseStatusException e){assertEquals(412,e.getStatusCode().value());return false;}});assertNotEquals(a.get(),b.get());}assertEquals(2,store.get(space,root.roadmapId()).version());assertEquals(2,events(root.roadmapId()));assertEquals(store.get(space,root.roadmapId()),store.history(space,root.roadmapId(),Long.MAX_VALUE,1).getFirst().snapshot());}
 @Test void relatedSemanticsNormalizeAndMetadataNoOpIsVersionStable(){var root=store.create(space,actor,"No-op","",trace);assertEquals(root,store.metadata(space,root.roadmapId(),actor,1,"No-op","",false,trace));var input=graph();var related=new RoadmapGraph.Edit(input.nodes(),List.of(new RoadmapGraph.EdgeEdit("new:r","RELATED_TO","new:b","new:a")));var value=store.graph(space,root.roadmapId(),actor,1,related,trace);var edge=value.edges().getFirst();assertTrue(edge.sourceNodeId().toString().compareTo(edge.targetNodeId().toString())<0);assertEquals(2,events(root.roadmapId()));}
 @Test void canonicalCatalogAndHistoryUseIndependentKeysetAndVersionCursors(){for(int i=0;i<22;i++)store.create(space,actor,"Catalog "+i,"",trace);var first=store.list(space,null,20);assertEquals(20,first.items().size());assertEquals(2,store.list(space,first.nextAfter(),20).items().size());assertTrue(store.list(actor,null,20).items().isEmpty());var id=first.items().getFirst().roadmapId();for(int v=1;v<=7;v++)store.metadata(space,id,actor,v,"Revision "+v,"",false,trace);var h=store.history(space,id,Long.MAX_VALUE,5);assertEquals(List.of(8L,7L,6L,5L,4L),h.stream().map(RoadmapStore.Revision::version).toList());assertEquals(List.of(3L,2L,1L),store.history(space,id,4,5).stream().map(RoadmapStore.Revision::version).toList());}
 @Test void oversizedCombinedSnapshotRollsBackNodesEdgesRootRevisionAndOutbox(){
  var root=store.create(space,actor,"Size", "\"".repeat(32768),trace);var nodes=new ArrayList<RoadmapGraph.NodeEdit>();var edges=new ArrayList<RoadmapGraph.EdgeEdit>();
  for(int n=0;n<100;n++)nodes.add(new RoadmapGraph.NodeEdit("new:n"+n,"가".repeat(200),"\"".repeat(2048)));
  for(int e=0;e<500;e++)edges.add(new RoadmapGraph.EdgeEdit("new:e"+e,"RELATED_TO","new:n"+(e/99),"new:n"+(e%99+1)));
  // Use unique cross-pairs, avoiding symmetric duplicates in the size fixture.
  edges.clear();outer:for(int a=0;a<100;a++)for(int b=a+1;b<100;b++){edges.add(new RoadmapGraph.EdgeEdit("new:e"+edges.size(),"RELATED_TO","new:n"+a,"new:n"+b));if(edges.size()==500)break outer;}
  var error=assertThrows(ResponseStatusException.class,()->store.graph(space,root.roadmapId(),actor,1,new RoadmapGraph.Edit(nodes,edges),trace));assertEquals(400,error.getStatusCode().value());assertEquals(root,store.get(space,root.roadmapId()));assertEquals(1,events(root.roadmapId()));assertEquals(0,sql.queryForObject("SELECT count(*) FROM roadmap_node WHERE roadmap_id=?",Integer.class,root.roadmapId()));assertEquals(0,sql.queryForObject("SELECT count(*) FROM roadmap_edge WHERE roadmap_id=?",Integer.class,root.roadmapId()));assertEquals(1,store.history(space,root.roadmapId(),Long.MAX_VALUE,10).size());
 }
 @Test void existingEdgeSemanticSwapIsAtomicAndRetiredEdgeCannotReturn(){
  var root=store.create(space,actor,"Swap","",trace);var input=graph();var value=store.graph(space,root.roadmapId(),actor,1,new RoadmapGraph.Edit(input.nodes(),List.of(new RoadmapGraph.EdgeEdit("new:e","PREREQUISITE_OF","new:a","new:b"),new RoadmapGraph.EdgeEdit("new:f","RELATED_TO","new:a","new:b"))),trace);var original=edit(value);var swapped=new RoadmapGraph.Edit(original.nodes(),List.of(new RoadmapGraph.EdgeEdit(original.edges().get(0).key(),original.edges().get(1).kind(),original.edges().get(1).source(),original.edges().get(1).target()),new RoadmapGraph.EdgeEdit(original.edges().get(1).key(),original.edges().get(0).kind(),original.edges().get(0).source(),original.edges().get(0).target())));var result=store.graph(space,root.roadmapId(),actor,2,swapped,trace);assertEquals(3,result.version());assertEquals(2,result.edges().size());var removed=store.graph(space,root.roadmapId(),actor,3,new RoadmapGraph.Edit(swapped.nodes(),List.of()),trace);assertThrows(ResponseStatusException.class,()->store.graph(space,root.roadmapId(),actor,4,swapped,trace));assertEquals(removed,store.get(space,root.roadmapId()));
 }
}
